// Decode the original native collision block, rather than duplicating a
// hand-authored arena grid. This also detects future changes to the pillar.
static std::vector<uint8_t> native_block(const std::vector<uint8_t>& rom,uint32_t pointer){
 const auto at=bank(rom,pointer);need(at+12<=rom.size(),"Native block descriptor in ROM");
 const size_t length=workshop::u32(rom,at),encoded=workshop::u32(rom,at+4),start=bank(rom,workshop::u32(rom,at+8));need(length&&start+encoded<=rom.size(),"Native block payload in ROM");
 std::span<const uint8_t> data(rom.data()+start,encoded);
 if(encoded<4||workshop::u32(data,0)!=0x434D5052){need(length<=encoded,"Raw native block is complete");return {data.begin(),data.begin()+length};}
 need(encoded>=32&&workshop::u32(data,16)==0x534D5352&&workshop::u32(data,24)==length,"Actual native SMSR header");
 size_t control=32,literal=32+workshop::u32(data,28);unsigned flags=0,bits=0;std::vector<uint8_t> out;out.reserve(length);
 while(out.size()<length){if(!bits){need(control+2<=encoded,"Native compression flag bounds");flags=workshop::u16(data,control);control+=2;bits=16;}
  if(flags&0x8000){need(literal<encoded,"Native compression literal bounds");out.push_back(data[literal++]);}
  else{need(control+2<=encoded,"Native compression pair bounds");const auto pair=workshop::u16(data,control);control+=2;const unsigned count=(pair>>12)+3,distance=(pair&4095)+1;need(distance<=out.size()&&count<=length-out.size(),"Native compression back-reference bounds");for(unsigned n=0;n<count;n++)out.push_back(out[out.size()-distance]);}
  flags=(flags<<1)&65535;--bits;
 }return out;
}
